#include <stdint.h>
#include <string.h>
#include "stm32f407xx.h"

#define BUF_SIZE 16
volatile uint16_t adc_buf[BUF_SIZE];
volatile uint32_t tick = 0;
volatile uint32_t dma_done = 1;

// SysTick 中斷 handler（每 1ms 觸發一次）
void SysTick_Handler(void)
{
    tick++;
}

void delay_ms(uint32_t ms)
{
    uint32_t start = tick;
    while ((tick - start) < ms);
}

void DMA2_Stream7_IRQHandler(void) {
	if (DMA2 -> HISR & (1 << 27)) {
		DMA2 -> HIFCR |= (1 << 27); // set 1 to clear interrupt register
		dma_done = 1;
	}
}

void uart_dma_send(const void *str, uint16_t len) {
	static uint8_t tx_buf[128];

	while (!dma_done) {};
	dma_done = 0;

	if (len > sizeof(tx_buf)) len = sizeof(tx_buf);
	memcpy(tx_buf, str, len);

	DMA2_Stream7 -> CR &= ~(1 << 0);
	while (DMA2_Stream7 -> CR & ( 1 << 0));

	DMA2 -> HIFCR |= (0x3F << 22); // clear stream7 flag

	DMA2_Stream7 -> NDTR = len;
	DMA2_Stream7 -> PAR = (uint32_t)&(USART1 -> DR);
	DMA2_Stream7 -> M0AR  = (uint32_t)tx_buf;

	DMA2_Stream7 -> CR = (4 << 25)    // Channel 4 (USART1_TX)
                       | (1 << 6)     // DIR = memory → peripheral
                       | (1 << 10)    // MINC = memory 地址遞增
                       | (1 << 4)     // TCIE = Transfer Complete 中斷
                       | (1 << 0);    // EN = 啟動
}

void uart_dma_send_char(char c) {
	uart_dma_send(&c, 1);
}

void uart_dma_send_str(char *str) {
	uart_dma_send(str, strlen(str));
}

void uart_print_temp(int32_t temp_x10)
{
	uart_dma_send_str("Temp: ");

    // 處理負溫度
    if (temp_x10 < 0)
    {
    	uart_dma_send_char('-');
        temp_x10 = -temp_x10;
    }

    int32_t integer = temp_x10 / 10;   // 例如 283 → 28
    int32_t decimal = temp_x10 % 10;   // 例如 283 → 3

    // 整數部分轉字串（最多 3 位數）
    // 例如 28 → '2', '8'
    char buf[4];
    int len = 0;

    if (integer == 0)
    {
        buf[len++] = '0';
    }
    else
    {
        // 先反向填入
        int32_t tmp = integer;
        while (tmp > 0)
        {
            buf[len++] = '0' + (tmp % 10);
            tmp /= 10;
        }
        // 反轉
        for (int i = 0; i < len / 2; i++)
        {
            char swap = buf[i];
            buf[i] = buf[len - 1 - i];
            buf[len - 1 - i] = swap;
        }
    }

    // 送出整數部分
    for (int i = 0; i < len; i++) {
    	uart_dma_send_char(buf[i]);
    }

    // 小數點 + 一位小數
    uart_dma_send_char('.');
    uart_dma_send_char('0' + decimal);

    uart_dma_send_str(" C\r\n");
}

void systick_init(void) {
    // 1. 設定 SysTick 每 1ms 中斷一次
    // 系統預設 clock = 16MHz
    // 16000000 / 1000 = 16000 counts per ms
    SYSTICK -> LOAD = 16000 - 1;   // reload value
    SYSTICK -> VAL  = 0;            // 清除目前值
    SYSTICK -> CTRL = 0x7;          // bit0=enable, bit1=tickint, bit2=clksource(內部clock)
}

void rcc_init(void) {
	RCC -> AHB1ENR |= (1 << 0);    // GPIOA（UART TX 用 PA9）
	RCC -> APB2ENR |= (1 << 8);    // ADC1
	RCC -> APB2ENR |= (1 << 4);    // USART1
	RCC -> AHB1ENR |= (1 << 22);   // DMA2
}

void gpio_init(void) {
	GPIOA -> MODER &= ~(0x3 << (9*2));
	GPIOA -> MODER |=  (0x2 << (9*2));  // AF mode 10
	GPIOA -> MODER &= ~(0x3 << (10*2));
	GPIOA -> MODER |=  (0x2 << (10*2)); // AF mode 10

	GPIOA -> AFRH  &= ~(0xF << ((9-8) * 4));
	GPIOA -> AFRH  |=  (0x7 << ((9-8) * 4));
}

void adc_init(void) {
	// 啟用內部溫度感測器
	ADC_COMMON -> CCR |= (1 << 23);        // TSVREFE = 1

	// 取樣時間：CH16 需要至少 10μs
	// ADC clock = APB2/2 = 8MHz，1 cycle = 0.125μs
	// 480 cycles × 0.125μs = 60μs（夠了）
	ADC1 -> SMPR1 |= (0x7 << (6 * 3));  // CH16 = 480 cycles
	// CH16 在 SMPR1 的位置：(16-10)*3 = bit[20:18]

	// 轉換序列：只轉 1 個 channel
	ADC1 -> SQR1 &= ~(0xF << 20);       // L = 0（1 次轉換）
	ADC1 -> SQR3 = 16;                   // 第一個轉換 = CH16

	// 開啟 ADC
	ADC1 -> CR2 |= (1 << 0);            // ADON
	// 開啟 continuous mode
	ADC1 -> CR2 |= (1 << 1);            // CONT
	// 開啟 DMA 請求
	ADC1 -> CR2 |= (1 << 8);            // DMA = 1
	// DDS bit：continuous mode 下每次轉換都發 DMA 請求
	ADC1 -> CR2 |= (1 << 9);            // DDS = 1
}

void dma_init(void) {
	// 確保 stream 關閉再設定
	DMA2_Stream0 -> CR &= ~(1 << 0);          // EN = 0
	while (DMA2_Stream0 -> CR & (1 << 0));    // 等待關閉完成

	// Channel 0（ADC1）
	DMA2_Stream0 -> CR &= ~(0x7 << 25);       // CHSEL = 000

	// 方向：peripheral → memory
	DMA2_Stream0 -> CR &= ~(0x3 << 6);        // DIR = 00

	// 資料寬度：16-bit（ADC 是 12-bit，放在 half-word）
	DMA2_Stream0 -> CR &= ~(0x3 << 11);
	DMA2_Stream0 -> CR |=  (0x1 << 11);       // MSIZE = 01（16-bit）
	DMA2_Stream0 -> CR &= ~(0x3 << 13);
	DMA2_Stream0 -> CR |=  (0x1 << 13);       // PSIZE = 01（16-bit）

	// Memory 位址遞增，Peripheral 不遞增
	DMA2_Stream0 -> CR |=  (1 << 10);         // MINC = 1
	DMA2_Stream0 -> CR &= ~(1 << 9);          // PINC = 0

	// ★ Circular mode
	DMA2_Stream0 -> CR |= (1 << 8);           // CIRC = 1

	// 來源與目的位址
	DMA2_Stream0 -> PAR  = ADC1_BASE + 0x4C;  // ADC_DR
	DMA2_Stream0 -> M0AR = (uint32_t)adc_buf;
	DMA2_Stream0 -> NDTR = BUF_SIZE;

	// 啟動
	DMA2_Stream0 -> CR |= (1 << 0);           // EN = 1
}

void uart_init(void) {
	USART1 -> BRR = 16000000 / 1200;    // baud rate
	USART1 -> CR1 |= (1 << 3);          // TE = 1
	USART1 -> CR1 |= (1 << 13);         // UE = 1
	USART1 -> CR3 = (1 << 7);
}

int main(void)
{
    systick_init();
    rcc_init();
    gpio_init();
	dma_init();
	adc_init();
	uart_init();

	ADC1 -> CR2 |= (1 << 30);  // SWSTART，啟動第一次轉換
	                          // continuous mode 會自動繼續

	NVIC -> ISER[2] = (1 << 6);

	while (1)
	{
	    // 算 buffer 平均值（降低雜訊）
	    uint32_t sum = 0;
	    for (int i = 0; i < BUF_SIZE; i++)
	        sum += adc_buf[i];
	    uint32_t avg = sum / BUF_SIZE;

	    // 換算溫度（用整數運算避免 float）
	    // Vsense_mV = avg * 3300 / 4095
	    // temp = (Vsense_mV - 760) / 25 + 25  （單位 0.1°C 避免小數）
	    int32_t vsense = avg * 3300 / 4095;
	    int32_t temp_x10 = (vsense - 760) * 10 / 25 + 250;

	    // 印出，例如 "Temp: 28.3 C"
	    uart_print_temp(temp_x10);

	    delay_ms(1000);
	}
}
